namespace NotificationsApp.Services;

public record Notification(int Id, string Message, DateTime Timestamp);

public class NotificationService
{
    private readonly List<Notification> _notifications = new();
    private int _nextId = 1;

    public NotificationService()
    {
        // Seed with initial fake data.
        _notifications.AddRange(new[]
        {
            CreateNotification("Welcome to the app!"),
            CreateNotification("Your profile was updated."),
            CreateNotification("You have a new follower."),
        });
    }

    public List<Notification> GetNotifications()
    {
        lock (_notifications)
        {
            return _notifications.OrderByDescending(n => n.Timestamp).ToList();
        }
    }

    /// <summary>
    /// Returns notifications added after the given timestamp.
    /// Simulates a new notification appearing roughly every 10 seconds.
    /// </summary>
    public List<Notification> GetNotificationsSince(DateTime since)
    {
        MaybeGenerateNew();

        lock (_notifications)
        {
            return _notifications
                .Where(n => n.Timestamp > since)
                .OrderByDescending(n => n.Timestamp)
                .ToList();
        }
    }

    private static readonly string[] FakeMessages =
    [
        "Deployment succeeded for project Alpha.",
        "New comment on your pull request.",
        "Build failed — check the logs.",
        "You were mentioned in a discussion.",
        "Security alert: dependency update available.",
        "Your subscription renews tomorrow.",
        "Scheduled maintenance at midnight UTC.",
    ];

    private void MaybeGenerateNew()
    {
        lock (_notifications)
        {
            // Roughly one new notification every 10 seconds.
            if (Random.Shared.Next(2) == 0)
            {
                var msg = FakeMessages[Random.Shared.Next(FakeMessages.Length)];
                _notifications.Add(CreateNotification(msg));
            }
        }
    }

    private Notification CreateNotification(string message)
    {
        return new Notification(_nextId++, message, DateTime.UtcNow.AddMilliseconds(_nextId));
    }
}

@page "/notifications"
@rendermode @(new InteractiveServerRenderMode(prerender: true))
@using NotificationsApp.Services
@inject NotificationService NotificationSvc
@implements IDisposable

<PageTitle>Notifications</PageTitle>

<h1>
    Notifications
    <span class="badge bg-primary rounded-pill ms-2">@_notifications.Count</span>
</h1>

@if (_notifications.Count == 0)
{
    <p><em>No notifications yet.</em></p>
}
else
{
    <ul class="list-group mt-3">
        @foreach (var n in _notifications)
        {
            <li class="list-group-item d-flex justify-content-between align-items-start">
                <span>@n.Message</span>
                <small class="text-muted ms-3 text-nowrap">@n.Timestamp.ToString("HH:mm:ss")</small>
            </li>
        }
    </ul>
}

@code {
    private List<Notification> _notifications = new();
    private CancellationTokenSource? _cts;
    private DateTime _lastCheck;

    // Runs during prerender AND when the component goes interactive.
    // On prerender this gives us server-rendered HTML with data.
    // On the interactive render the same data is still in place.
    protected override void OnInitialized()
    {
        if (_notifications.Count == 0)
        {
            _notifications = NotificationSvc.GetNotifications();
            _lastCheck = _notifications.Count > 0
                ? _notifications.Max(n => n.Timestamp)
                : DateTime.UtcNow;
        }
    }

    // Called only once when the circuit is established (interactive).
    // Never fires during static SSR prerender.
    protected override void OnAfterRender(bool firstRender)
    {
        if (firstRender)
        {
            _cts = new CancellationTokenSource();
            _ = PollForNotificationsAsync(_cts.Token);
        }
    }

    private async Task PollForNotificationsAsync(CancellationToken ct)
    {
        while (!ct.IsCancellationRequested)
        {
            try
            {
                await Task.Delay(TimeSpan.FromSeconds(5), ct);
            }
            catch (TaskCanceledException)
            {
                break;
            }

            var newer = NotificationSvc.GetNotificationsSince(_lastCheck);
            if (newer.Count > 0)
            {
                _notifications.InsertRange(0, newer);
                _lastCheck = newer.Max(n => n.Timestamp);
                await InvokeAsync(StateHasChanged);
            }
        }
    }

    public void Dispose()
    {
        _cts?.Cancel();
        _cts?.Dispose();
    }
}

